const b=$input.first().json.body ?? $input.first().json;
const fail=(message)=>[{json:{valid:false,response:{ok:false,error:'invalid_attachment',message}}}];
if(!b||typeof b!=='object'||Array.isArray(b))return fail('Нужен один файл.');
const {fileName,mimeType,dataUrl}=b;
if(typeof fileName!=='string'||fileName.length<1||fileName.length>160||/[\/\\\x00-\x1f]/.test(fileName))return fail('Недопустимое имя файла.');
const ext=fileName.toLowerCase().split('.').pop();
const mime={pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',xls:'application/vnd.ms-excel',csv:'text/csv',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp'}[ext];
if(!mime||mimeType!==mime)return fail('Поддерживаются PDF, DOCX, XLSX, XLS, CSV, JPEG, PNG, WebP. Тип файла должен совпадать с расширением.');
if(typeof dataUrl!=='string'||dataUrl.length>6990800||!dataUrl.startsWith('data:'+mime+';base64,'))return fail('Максимум 5 МБ; нужен файл в base64.');
const base64=dataUrl.slice(dataUrl.indexOf(',')+1);
if(!base64.length||base64.length%4!==0||!/^[A-Za-z0-9+/]*={0,2}$/.test(base64))return fail('Некорректное кодирование файла.');
let bytes;try{bytes=Buffer.from(base64,'base64');}catch{return fail('Некорректный файл.');}
if(!bytes.length||bytes.length>5*1024*1024||bytes.toString('base64')!==base64)return fail('Максимум 5 МБ; пустые файлы не поддерживаются.');
const hex=bytes.subarray(0,12).toString('hex');
const zip=hex.startsWith('504b0304');
const signature=ext==='pdf'?bytes.subarray(0,5).toString()==='%PDF-':ext==='docx'?zip&&bytes.includes(Buffer.from('word/document.xml')):ext==='xlsx'?zip&&bytes.includes(Buffer.from('xl/workbook.xml')):ext==='xls'?hex.startsWith('d0cf11e0a1b11ae1'):ext==='csv'?!bytes.includes(0)&&!hex.startsWith('4d5a'):ext==='jpg'||ext==='jpeg'?hex.startsWith('ffd8ff'):ext==='png'?hex.startsWith('89504e470d0a1a0a'):ext==='webp'?hex.startsWith('52494646')&&bytes.subarray(8,12).toString()==='WEBP':false;
if(!signature)return fail('Содержимое не соответствует формату файла.');
const isImage=mime.startsWith('image/');
const content=isImage?{type:'input_image',image_url:dataUrl,detail:'auto'}:{type:'input_file',filename:fileName,file_data:dataUrl};
return [{json:{valid:true,file_name:fileName,is_image:isImage,is_spreadsheet:['xlsx','xls','csv'].includes(ext)},binary:{data:{data:base64,mimeType:mime,fileName}}}];

const r=$input.first().json;
const source=$('Validate attachment').first().json;
const text=(Array.isArray(r.output)?r.output:[]).filter(x=>x.type==='message').flatMap(x=>Array.isArray(x.content)?x.content:[]).filter(x=>x.type==='output_text'&&typeof x.text==='string').map(x=>x.text).join('\n').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'').trim();
if(!text||r.status!=='completed')return [{json:{status:502,response:{ok:false,error:'extraction_unavailable',message:'Не удалось полностью прочитать файл. Попробуйте меньший файл или укажите артикул текстом.'}}}];
const warning='Распознавание может содержать ошибки. Проверьте артикулы и количества; цены и наличие проверяются отдельно по БД.'+(source.is_spreadsheet?' Таблицы: обрабатываются до первых 1000 строк каждого листа.':'')+(text.length>6000?' Текст сокращён до 6000 символов.':'');
return [{json:{status:200,response:{ok:true,file_name:source.file_name,extracted_text:text.slice(0,6000),warning}}}];
